content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-color: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --success-color: #22c55e;
  --danger-color: #ef4444;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 24px;
  background-color: var(--card-bg);
  border-radius: 16px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 16px;
}

.header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-color);
}

.timer-box {
  font-size: 1.25rem;
  font-weight: 600;
  background-color: #eff6ff;
  color: var(--primary-color);
  padding: 6px 16px;
  border-radius: 9999px;
  border: 1px solid #bfdbfe;
}

.word-display {
  background-color: #f1f5f9;
  border-radius: 12px;
  padding: 32px 24px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 160px;
  justify-content: center;
}

.japanese-text {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-muted);
}

.romaji-text {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  font-family: monospace;
  color: var(--text-color);
}

.typed-text {
  color: var(--primary-color);
}

.input-area {
  width: 100%;
  padding: 16px;
  font-size: 1.25rem;
  border: 2px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s;
  font-family: monospace;
  text-align: center;
}

.input-area:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.stats-bar {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  text-align: center;
}

.stat-item {
  background-color: #f8fafc;
  padding: 12px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
}

.stat-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.stat-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-color);
}

.btn {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
  width: 100%;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.result-card {
  display: flex;
  flex-direction: column;
  gap: 20px;
  text-align: center;
  padding: 24px 0;
}

.result-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-color);
}

.result-stats {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

@media (max-width: 480px) {
  .app-container {
    padding: 16px;
    margin: 12px;
    max-width: 100%;
  }

  .romaji-text {
    font-size: 1.5rem;
  }
}

export type GameStatus = 'ready' | 'playing' | 'finished';

export interface WordItem {
  id: number;
  japanese: string;
  romaji: string;
}

import { useState, useEffect, useRef } from 'react';
import { GameStatus, WordItem } from './types';

const INITIAL_WORDS: WordItem[] = [
  { id: 1, japanese: 'りんご', romaji: 'ringo' },
  { id: 2, japanese: 'みかん', romaji: 'mikan' },
  { id: 3, japanese: 'ばなな', romaji: 'banana' },
  { id: 4, japanese: 'すいか', romaji: 'suika' },
  { id: 5, japanese: 'めろん', romaji: 'meron' },
  { id: 6, japanese: 'いちご', romaji: 'ichigo' },
  { id: 7, japanese: 'ぱいなっぷる', romaji: 'painappuru' },
  { id: 8, japanese: 'きゅうり', romaji: 'kyuuri' },
  { id: 9, japanese: 'とまと', romaji: 'tomato' },
  { id: 10, japanese: 'にんじん', romaji: 'ninjin' },
];

export default function App() {
  const [gameStatus, setGameStatus] = useState<GameStatus>('ready');
  const [timeLeft, setTimeLeft] = useState<number>(60);
  const [currentWordIndex, setCurrentWordIndex] = useState<number>(0);
  const [inputVal, setInputVal] = useState<string>('');

  const [totalTyped, setTotalTyped] = useState<number>(0);
  const [correctTyped, setCorrectTyped] = useState<number>(0);
  const [wordsCompleted, setWordsCompleted] = useState<number>(0);

  const inputRef = useRef<HTMLInputElement>(null);

  const currentWord = INITIAL_WORDS[currentWordIndex % INITIAL_WORDS.length];

  // タイマー処理
  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (gameStatus === 'playing' && timeLeft > 0) {
      timer = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0 && gameStatus === 'playing') {
      setGameStatus('finished');
    }
    return () => clearInterval(timer);
  }, [gameStatus, timeLeft]);

  // フォーカス管理
  useEffect(() => {
    if (gameStatus === 'playing' && inputRef.current) {
      inputRef.current.focus();
    }
  }, [gameStatus]);

  const startGame = () => {
    setGameStatus('playing');
    setTimeLeft(60);
    setCurrentWordIndex(0);
    setInputVal('');
    setTotalTyped(0);
    setCorrectTyped(0);
    setWordsCompleted(0);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (gameStatus !== 'playing') return;
    const value = e.target.value;
    const romaji = currentWord.romaji;

    // 入力文字数が増えた分をカウント
    if (value.length > inputVal.length) {
      setTotalTyped((prev) => prev + 1);
      // 正しいキーかチェック (前方一致)
      if (romaji.startsWith(value)) {
        setCorrectTyped((prev) => prev + 1);
      }
    }

    setInputVal(value);

    // 単語クリア判定
    if (value === romaji) {
      setWordsCompleted((prev) => prev + 1);
      setCurrentWordIndex((prev) => prev + 1);
      setInputVal('');
    }
  };

  const accuracy = totalTyped > 0 ? Math.round((correctTyped / totalTyped) * 100) : 100;

  return (
    <div className="app-container">
      <div className="header">
        <h1>ローマ字タイピング練習</h1>
        {gameStatus === 'playing' && (
          <div className="timer-box">残り時間: {timeLeft}秒</div>
        )}
      </div>

      {gameStatus === 'ready' && (
        <div className="result-card">
          <div className="result-title">タイピングゲームへようこそ！</div>
          <p style={{ color: 'var(--text-muted)' }}>
            60秒間でできるだけ多くのローマ字を入力しましょう。<br />
            「スタート」ボタンを押すとゲームが始まります。
          </p>
          <button className="btn btn-primary" onClick={startGame}>
            スタート
          </button>
        </div>
      )}

      {gameStatus === 'playing' && (
        <>
          <div className="word-display">
            <div className="japanese-text">{currentWord.japanese}</div>
            <div className="romaji-text">
              <span className="typed-text">{currentWord.romaji.substring(0, inputVal.length)}</span>
              {currentWord.romaji.substring(inputVal.length)}
            </div>
          </div>

          <input
            ref={inputRef}
            type="text"
            className="input-area"
            value={inputVal}
            onChange={handleInputChange}
            placeholder="ここに入力..."
            autoFocus
          />

          <div className="stats-bar">
            <div className="stat-item">
              <div className="stat-label">クリア単語</div>
              <div className="stat-value">{wordsCompleted}</div>
            </div>
            <div className="stat-item">
              <div className="stat-label">入力文字数</div>
              <div className="stat-value">{totalTyped}</div>
            </div>
            <div className="stat-item">
              <div className="stat-label">正確率</div>
              <div className="stat-value">{accuracy}%</div>
            </div>
          </div>
        </>
      )}

      {gameStatus === 'finished' && (
        <div className="result-card">
          <div className="result-title">ゲーム終了！</div>
          <div className="result-stats">
            <div className="stat-item" style={{ padding: '16px' }}>
              <div className="stat-label">クリアした単語数</div>
              <div className="stat-value" style={{ fontSize: '1.5rem' }}>{wordsCompleted} 個</div>
            </div>
            <div className="stat-item" style={{ padding: '16px' }}>
              <div className="stat-label">総入力文字数</div>
              <div className="stat-value" style={{ fontSize: '1.5rem' }}>{totalTyped} 文字</div>
            </div>
            <div className="stat-item" style={{ padding: '16px' }}>
              <div className="stat-label">正確率</div>
              <div className="stat-value" style={{ fontSize: '1.5rem' }}>{accuracy} %</div>
            </div>
          </div>
          <button className="btn btn-primary" onClick={startGame}>
            もう一度プレイする
          </button>
        </div>
      )}
    </div>
  );
}
